SELECT routine_name, routine_type, data_type FROM information_schema.routines WHERE routine_schema = 'app' AND (routine_name ILIKE '%tournament%' OR routine_name ILIKE '%league%' OR routine_name ILIKE '%game%' OR routine_name ILIKE '%match%' OR routine_name ILIKE '%multiplayer%' OR routine_name ILIKE '%arena%' OR routine_name ILIKE '%kellenge%' OR routine_name ILIKE '%bracket%') ORDER BY routine_name;
